INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q1', 'Điều động tàu rời cầu đi theo hướng đậu, có nước chảy từ mũi về lái, khi mũi tàu ngã được góc khoảng 300 :', 'gk2_dieudong', 1), ('gk2_dieudong_q2', 'Điều động tàu rời cầu đi theo hướng đậu, có nước chảy từ lái về mũi, muốn ra lái trước phải:', 'gk2_dieudong', 2), ('gk2_dieudong_q3', 'Điều động tàu rời cầu đi theo hướng đậu, có nước chảy từ lái về mũi, khi lái tàu ngã được góc khoảng 300 thì:', 'gk2_dieudong', 3), ('gk2_dieudong_q4', 'Điều động tàu rời cầu đi theo hướng đậu, có gió ngoài cầu thổi vào muốn ra lái trước thì:', 'gk2_dieudong', 4), ('gk2_dieudong_q5', 'Điều động tàu cập cầu ngược nước, khi mũi tàu vào sát cầu phải:', 'gk2_dieudong', 5), ('gk2_dieudong_q6', 'Điều động tàu cập cầu ngược nước, khi mũi tàu gần tới cầu, nếu trớn còn mạnh phải phá trớn bằng cách:', 'gk2_dieudong', 6), ('gk2_dieudong_q7', 'Điều động tàu cập cầu xuôi nước, khi lái tàu vào sát cầu phải:', 'gk2_dieudong', 7), ('gk2_dieudong_q8', 'Điều động tàu cập cầu, gió trong cầu thổi ra, khi bắt được dây chéo mũi thì:', 'gk2_dieudong', 8), ('gk2_dieudong_q9', 'Khi điều động tàu cập cầu, cập phao, thả neo, chạy qua cầu thì thường lựa chọn:', 'gk2_dieudong', 9), ('gk2_dieudong_q10', 'Khi có gió lớn từ ngoài cầu thổi vào thì sử dụng phương pháp điều động cập an toàn nhất là:', 'gk2_dieudong', 10), ('gk2_dieudong_q11', 'Nguyên tắc điều động tàu cập cầu:', 'gk2_dieudong', 11), ('gk2_dieudong_q12', 'Điều động tàu chạy trên đường trường thì thường lựa chọn:', 'gk2_dieudong', 12), ('gk2_dieudong_q13', 'Tàu chạy ngược nước thì:', 'gk2_dieudong', 13), ('gk2_dieudong_q14', 'Tàu chạy xuôi nước thì:', 'gk2_dieudong', 14), ('gk2_dieudong_q15', 'Để đề phòng hiện tượng hai tàu hút nhau, khi vượt nhau, tốc độ của tàu vượt và tàu bị vượt:', 'gk2_dieudong', 15), ('gk2_dieudong_q16', 'Để đề phòng hiện tượng hai tàu hút nhau, khi tránh nhau, tốc độ của hai tàu:', 'gk2_dieudong', 16), ('gk2_dieudong_q17', 'Khi tàu chạy trong sông, kênh hẹp thì:', 'gk2_dieudong', 17), ('gk2_dieudong_q18', 'Điều động tàu rời cầu đi theo hướng đậu khi có nước chảy từ mũi về lái, muốn ra mũi trước phải:', 'gk2_dieudong', 18), ('gk2_dieudong_q19', 'Tàu đang chạy mà có người ngã xuống nước thì người phát hiện đầu tiên phải:', 'gk2_dieudong', 19), ('gk2_dieudong_q20', 'Tàu đang chạy mà có người ngã xuống nước thì khi điều động tàu cứu người phải để người ngã ngang ca bin hay chỗ dễ vớt nhất, cách mạn tàu khoảng:', 'gk2_dieudong', 20), ('gk2_dieudong_q21', 'Tàu đang chạy mà có người ngã xuống nước thì khi điều động tàu cứu người phải để người ngã phía:', 'gk2_dieudong', 21), ('gk2_dieudong_q22', 'Tàu đang chạy xuôi nước mà có người ngã xuống nước thì:', 'gk2_dieudong', 22), ('gk2_dieudong_q23', 'Tàu đang chạy ngược nước mà có người ngã xuống nước thì:', 'gk2_dieudong', 23), ('gk2_dieudong_q24', 'Tàu đang chạy mà có người ngã xuống nước thì số phao ném cho người ngã là:', 'gk2_dieudong', 24), ('gk2_dieudong_q25', 'Khi tàu đang hành trình có người ngã xuống nước,  phải  cho người nhảy ngay xuống để cứu không:', 'gk2_dieudong', 25), ('gk2_dieudong_q26', 'Điều động tàu thả một neo ngược nước, khi neo chạm đáy nhấp nhẹ cần hãm để neo bám đáy, ban đầu xông một lượng dây neo bằng:', 'gk2_dieudong', 26), ('gk2_dieudong_q27', 'Tàu bị trôi neo do nước chảy siết thì phải?', 'gk2_dieudong', 27), ('gk2_dieudong_q28', 'Tàu bị trôi neo do chất đáy bám không tốt thì phải?', 'gk2_dieudong', 28), ('gk2_dieudong_q29', 'Tàu bị trôi neo do nước thủy triều dâng lên thì phải?', 'gk2_dieudong', 29), ('gk2_dieudong_q30', 'khi tàu đang chạy bị mắc cạn, phải xử lý như thế nào để hạn chế các rủi ro?', 'gk2_dieudong', 30), ('gk2_dieudong_q31', 'Điều khiển tàu đi đường có ảnh hưởng của gió, nước ngang, để trừ hao độ dạt người điều khiển cần:', 'gk2_dieudong', 31), ('gk2_dieudong_q32', 'Nguyên nhân nào thường xảy ra nhiều nhất làm cho tàu bị thủng?', 'gk2_dieudong', 32), ('gk2_dieudong_q33', 'Biện pháp đề phòng tàu bị thủng?', 'gk2_dieudong', 33), ('gk2_dieudong_q34', 'Việc đầu tiên phải làm khi tàu bị thủng?', 'gk2_dieudong', 34), ('gk2_dieudong_q35', 'Phương pháp điều động tàu về bến sau khi bịt lỗ thủy tạm thời:', 'gk2_dieudong', 35), ('gk2_dieudong_q36', 'Phương pháp tự đưa tàu ra cạn khi tàu bị mắc cạn trên đá?', 'gk2_dieudong', 36), ('gk2_dieudong_q37', 'Phương pháp nào hay được sử dụng nhiều nhất khi tự đưa tàu ra cạn trường hợp tàu bị mắc cạn trên bùn cát?', 'gk2_dieudong', 37), ('gk2_dieudong_q38', 'Khi chạy trong đường chập thì?', 'gk2_dieudong', 38), ('gk2_dieudong_q39', 'Khi chạy trong đường chập mà có gió ngang thì?', 'gk2_dieudong', 39), ('gk2_dieudong_q40', 'Để hai tàu vượt nhau an toàn thì?', 'gk2_dieudong', 40), ('gk2_dieudong_q41', 'Để hai tàu tránh nhau an toàn thì?', 'gk2_dieudong', 41), ('gk2_dieudong_q42', 'Để tàu chạy trong sông, kênh hẹp an toàn thì?', 'gk2_dieudong', 42), ('gk2_dieudong_q43', 'Điều động tàu khi có xương mù thì?', 'gk2_dieudong', 43), ('gk2_dieudong_q44', 'Điều động tàu khi có xương mù dày đặc không thể chạy được thì?', 'gk2_dieudong', 44);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q1_a1', 'Bẻ lái ra ngoài cầu, cho máy tới nhẹ, tàu có trớn tới, dây chùng, mở dây.', 'gk2_dieudong_q1'), ('gk2_dieudong_q1_a2', 'Bẻ lái vào trong cầu, cho máy tới nhẹ, tàu có trớn tới, dây chùng, mở dây.', 'gk2_dieudong_q1'), ('gk2_dieudong_q1_a3', 'Bánh lái để 00, cho máy tới nhẹ, tàu có trớn tới, dây chùng, mở dây.', 'gk2_dieudong_q1'), ('gk2_dieudong_q1_a4', 'Bẻ lái ra ngoài cầu, mở dây.', 'gk2_dieudong_q1'), ('gk2_dieudong_q2_a1', 'Để lại dây dọc lái, bẻ lái ra ngoài.', 'gk2_dieudong_q2'), ('gk2_dieudong_q2_a2', 'Để lại dây chéo mũi, bẻ lái ra ngoài.', 'gk2_dieudong_q2'), ('gk2_dieudong_q2_a3', 'Để lại dây ngang mũi, bẻ lái ra ngoài.', 'gk2_dieudong_q2'), ('gk2_dieudong_q2_a4', 'Để lại dây chéo, bẻ lái vào trong.', 'gk2_dieudong_q2'), ('gk2_dieudong_q3_a1', 'Bẻ lái ra ngoài cầu, cho máy lùi nhẹ, tàu có trớn lùi, dây chùng, mở dây', 'gk2_dieudong_q3'), ('gk2_dieudong_q3_a2', 'Bẻ lái vào trong cầu, cho máy lùi nhẹ, tàu có trớn lùi, dây chùng, mở dây.', 'gk2_dieudong_q3'), ('gk2_dieudong_q3_a3', 'Bánh lái để 00, cho máy lùi nhẹ, tàu có trớn lùi, dây chùng, mở dây.', 'gk2_dieudong_q3'), ('gk2_dieudong_q3_a4', 'Bẻ lái ra ngoài cầu, mở dây', 'gk2_dieudong_q3'), ('gk2_dieudong_q4_a1', 'Để lại dây chéo mũi, bẻ lái ra ngoài, cho máy tới.', 'gk2_dieudong_q4'), ('gk2_dieudong_q4_a2', 'Để lại dây chéo mũi, bẻ lái vào trong, cho máy tới.', 'gk2_dieudong_q4'), ('gk2_dieudong_q4_a3', 'Để lại dây dọc mũi, bẻ lái ra ngoài, cho máy lùi.', 'gk2_dieudong_q4'), ('gk2_dieudong_q4_a4', 'Để lại dây ngang mũi, bẻ lái ra ngoài, cho máy tới.', 'gk2_dieudong_q4'), ('gk2_dieudong_q5_a1', 'Bắt dây ngang mũi, bẻ lái ra ngoài.', 'gk2_dieudong_q5'), ('gk2_dieudong_q5_a2', 'Bắt dây dọc mũi, bẻ lái ra ngoài.', 'gk2_dieudong_q5'), ('gk2_dieudong_q5_a3', 'Bắt dây dọc mũi, bẻ lái vào trong.', 'gk2_dieudong_q5'), ('gk2_dieudong_q5_a4', 'Bắt dây chéo mũi, bẻ lái ra ngoài.', 'gk2_dieudong_q5'), ('gk2_dieudong_q6_a1', 'Cho máy tới.', 'gk2